/* Lei seca da Revisão — redação oficial, sem texto autoral. Gerado por scripts/build-lei-revisao.mjs. */
(function(g){g.BC_LEI_REVISAO=g.BC_LEI_REVISAO||{};g.BC_LEI_REVISAO["cpp"]=g.BC_LEI_REVISAO["cpp"]||{};g.BC_LEI_REVISAO["cpp"][12]=[{"key":"cpp:155","law":"cpp","ref":"155","label":"CPP — art. 155","paragraphs":["Art. 155. O juiz formará sua convicção pela livre apreciação da prova produzida em contraditório judicial, não podendo fundamentar sua decisão exclusivamente nos elementos informativos colhidos na investigação, ressalvadas as provas cautelares, não repetíveis e antecipadas. (“Caput” do artigo com redação dada pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Somente quanto ao estado das pessoas serão observadas as restrições estabelecidas na lei civil. (Parágrafo único acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:156","law":"cpp","ref":"156","label":"CPP — art. 156","paragraphs":["Art. 156. A prova da alegação incumbirá a quem a fizer, sendo, porém, facultado ao juiz de ofício: (“Caput” do artigo com redação dada pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","I - ordenar, mesmo antes de iniciada a ação penal, a produção antecipada de provas consideradas urgentes e relevantes, observando a necessidade, adequação e proporcionalidade da medida; (Inciso acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","II - determinar, no curso da instrução, ou antes de proferir sentença, a realização de diligências para dirimir dúvida sobre ponto relevante. (Inciso acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:3-A","law":"cpp","ref":"3-A","label":"CPP — art. 3-A","paragraphs":["Art. 3º-A. O processo penal terá estrutura acusatória, vedadas a iniciativa do juiz na fase de investigação e a substituição da atuação probatória do órgão de acusação. (Artigo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação) (Vide ADIs nºs 6.298, 6.299, 6.300 e 6.305, cuja Decisão foi publicada no DOU de 4/9/2023)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cf:5","law":"cf","ref":"5","label":"Constituição Federal — art. 5","paragraphs":["Art. 5º Todos são iguais perante a lei, sem distinção de qualquer natureza, garantindo-se aos brasileiros e aos estrangeiros residentes no País a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, nos termos seguintes:","I - homens e mulheres são iguais em direitos e obrigações, nos termos desta Constituição;","II - ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de lei;","III - ninguém será submetido a tortura nem a tratamento desumano ou degradante;","IV - é livre a manifestação do pensamento, sendo vedado o anonimato;","V - é assegurado o direito de resposta, proporcional ao agravo, além da indenização por dano material, moral ou à imagem;","VI - é inviolável a liberdade de consciência e de crença, sendo assegurado o livre exercício dos cultos religiosos e garantida, na forma da lei, a proteção aos locais de culto e a suas liturgias;","VII - é assegurada, nos termos da lei, a prestação de assistência religiosa nas entidades civis e militares de internação coletiva;","VIII - ninguém será privado de direitos por motivo de crença religiosa ou de convicção filosófica ou política, salvo se as invocar para eximir-se de obrigação legal a todos imposta e recusar-se a cumprir prestação alternativa, fixada em lei;","IX - é livre a expressão da atividade intelectual, artística, científica e de comunicação, independentemente de censura ou licença;","X - são invioláveis a intimidade, a vida privada, a honra e a imagem das pessoas, assegurado o direito a indenização pelo dano material ou moral decorrente de sua violação;","XI - a casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, durante o dia, por determinação judicial;","XII - é inviolável o sigilo da correspondência e das comunicações telegráficas, de dados e das comunicações telefônicas, salvo, no último caso, por ordem judicial, nas hipóteses e na forma que a lei estabelecer para fins de investigação criminal ou instrução processual penal;","XIII - é livre o exercício de qualquer trabalho, ofício ou profissão, atendidas as qualificações profissionais que a lei estabelecer;","XIV - é assegurado a todos o acesso à informação e resguardado o sigilo da fonte, quando necessário ao exercício profissional;","XV - é livre a locomoção no território nacional em tempo de paz, podendo qualquer pessoa, nos termos da lei, nele entrar, permanecer ou dele sair com seus bens;","XVI - todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, independentemente de autorização, desde que não frustrem outra reunião anteriormente convocada para o mesmo local, sendo apenas exigido prévio aviso à autoridade competente;","XVII - é plena a liberdade de associação para fins lícitos, vedada a de caráter paramilitar;","XVIII - a criação de associações e, na forma da lei, a de cooperativas independem de autorização, sendo vedada a interferência estatal em seu funcionamento;","XIX - as associações só poderão ser compulsoriamente dissolvidas ou ter suas atividades suspensas por decisão judicial, exigindo-se, no primeiro caso, o trânsito em julgado;","XX - ninguém poderá ser compelido a associar-se ou a permanecer associado;","XXI - as entidades associativas, quando expressamente autorizadas, têm legitimidade para representar seus filiados judicial ou extrajudicialmente;","XXII - é garantido o direito de propriedade;","XXIII - a propriedade atenderá a sua função social;","XXIV - a lei estabelecerá o procedimento para desapropriação por necessidade ou utilidade pública, ou por interesse social, mediante justa e prévia indenização em dinheiro, ressalvados os casos previstos nesta Constituição;","XXV - no caso de iminente perigo público, a autoridade competente poderá usar de propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano;","XXVI - a pequena propriedade rural, assim definida em lei, desde que trabalhada pela família, não será objeto de penhora para pagamento de débitos decorrentes de sua atividade produtiva, dispondo a lei sobre os meios de financiar o seu desenvolvimento;","XXVII - aos autores pertence o direito exclusivo de utilização, publicação ou reprodução de suas obras, transmissível aos herdeiros pelo tempo que a lei fixar;","XXVIII - são assegurados, nos termos da lei:","a) a proteção às participações individuais em obras coletivas e à reprodução da imagem e voz humanas, inclusive nas atividades desportivas;","b) o direito de fiscalização do aproveitamento econômico das obras que criarem ou de que participarem aos criadores, aos intérpretes e às respectivas representações sindicais e associativas;","XXIX - a lei assegurará aos autores de inventos industriais privilégio temporário para sua utilização, bem como proteção às criações industriais, à propriedade das marcas, aos nomes de empresas e a outros signos distintivos, tendo em vista o interesse social e o desenvolvimento tecnológico e econômico do País;","XXX - é garantido o direito de herança;","XXXI - a sucessão de bens de estrangeiros situados no País será regulada pela lei brasileira em benefício do cônjuge ou dos filhos brasileiros, sempre que não lhes seja mais favorável a lei pessoal do de cujus;","XXXII - o Estado promoverá, na forma da lei, a defesa do consumidor;","XXXIII - todos têm direito a receber dos órgãos públicos informações de seu interesse particular, ou de interesse coletivo ou geral, que serão prestadas no prazo da lei, sob pena de responsabilidade, ressalvadas aquelas cujo sigilo seja imprescindível à segurança da sociedade e do Estado;","XXXIV - são a todos assegurados, independentemente do pagamento de taxas:","a) o direito de petição aos poderes públicos em defesa de direitos ou contra ilegalidade ou abuso de poder;","b) a obtenção de certidões em repartições públicas, para defesa de direitos e esclarecimento de situações de interesse pessoal;","XXXV - a lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito;","XXXVI - a lei não prejudicará o direito adquirido, o ato jurídico perfeito e a coisa julgada;","XXXVII - não haverá juízo ou tribunal de exceção;","XXXVIII - é reconhecida a instituição do júri, com a organização que lhe der a lei, assegurados:","a) a plenitude de defesa;","b) o sigilo das votações;","c) a soberania dos veredictos;","d) a competência para o julgamento dos crimes dolosos contra a vida;","XXXIX - não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal;","XL - a lei penal não retroagirá, salvo para beneficiar o réu;","XLI - a lei punirá qualquer discriminação atentatória dos direitos e liberdades fundamentais;","XLII - a prática do racismo constitui crime inafiançável e imprescritível, sujeito à pena de reclusão, nos termos da lei;","XLIII - a lei considerará crimes inafiançáveis e insuscetíveis de graça ou anistia a prática da tortura, o tráfico ilícito de entorpecentes e drogas afins, o terrorismo e os definidos como crimes hediondos, por eles respondendo os mandantes, os executores e os que, podendo evitá-los, se omitirem;","XLIV - constitui crime inafiançável e imprescritível a ação de grupos armados, civis ou militares, contra a ordem constitucional e o Estado democrático;","XLV - nenhuma pena passará da pessoa do condenado, podendo a obrigação de reparar o dano e a decretação do perdimento de bens ser, nos termos da lei, estendidas aos sucessores e contra eles executadas, até o limite do valor do patrimônio transferido;","XLVI - a lei regulará a individualização da pena e adotará, entre outras, as seguintes:","a) privação ou restrição da liberdade;","b) perda de bens;","c) multa;","d) prestação social alternativa;","e) suspensão ou interdição de direitos;","XLVII - não haverá penas:","a) de morte, salvo em caso de guerra declarada, nos termos do art. 84, XIX;","b) de caráter perpétuo;","c) de trabalhos forçados;","d) de banimento;","e) cruéis;","XLVIII - a pena será cumprida em estabelecimentos distintos, de acordo com a natureza do delito, a idade e o sexo do apenado;","XLIX - é assegurado aos presos o respeito à integridade física e moral;","L - às presidiárias serão asseguradas condições para que possam permanecer com seus filhos durante o período de amamentação;","LI - nenhum brasileiro será extraditado, salvo o naturalizado, em caso de crime comum, praticado antes da naturalização, ou de comprovado envolvimento em tráfico ilícito de entorpecentes e drogas afins, na forma da lei;","LII - não será concedida extradição de estrangeiro por crime político ou de opinião;","LIII - ninguém será processado nem sentenciado senão pela autoridade competente;","LIV - ninguém será privado da liberdade ou de seus bens sem o devido processo legal;","LV - aos litigantes, em processo judicial ou administrativo, e aos acusados em geral são assegurados o contraditório e a ampla defesa, com os meios e recursos a ela inerentes;","LVI - são inadmissíveis, no processo, as provas obtidas por meios ilícitos;","LVII - ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória;","LVIII - o civilmente identificado não será submetido a identificação criminal, salvo nas hipóteses previstas em lei;","LIX - será admitida ação privada nos crimes de ação pública, se esta não for intentada no prazo legal;","LX - a lei só poderá restringir a publicidade dos atos processuais quando a defesa da intimidade ou o interesse social o exigirem;","LXI - ninguém será preso senão em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente, salvo nos casos de transgressão militar ou crime propriamente militar, definidos em lei;","LXII - a prisão de qualquer pessoa e o local onde se encontre serão comunicados imediatamente ao juiz competente e à família do preso ou à pessoa por ele indicada;","LXIII - o preso será informado de seus direitos, entre os quais o de permanecer calado, sendo-lhe assegurada a assistência da família e de advogado;","LXIV - o preso tem direito à identificação dos responsáveis por sua prisão ou por seu interrogatório policial;","LXV - a prisão ilegal será imediatamente relaxada pela autoridade judiciária;","LXVI - ninguém será levado à prisão ou nela mantido quando a lei admitir a liberdade provisória, com ou sem fiança;","LXVII - não haverá prisão civil por dívida, salvo a do responsável pelo inadimplemento voluntário e inescusável de obrigação alimentícia e a do depositário infiel;","LXVIII - conceder-se-á habeas corpus sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder;","LXIX - conceder-se-á mandado de segurança para proteger direito líquido e certo, não amparado por habeas corpus ou habeas data, quando o responsável pela ilegalidade ou abuso de poder for autoridade pública ou agente de pessoa jurídica no exercício de atribuições do poder público;","LXX - o mandado de segurança coletivo pode ser impetrado por:","a) partido político com representação no Congresso Nacional;","b) organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos um ano, em defesa dos interesses de seus membros ou associados;","LXXI - conceder-se-á mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania;","LXXII - conceder-se-á habeas data:","a) para assegurar o conhecimento de informações relativas à pessoa do impetrante, constantes de registros ou bancos de dados de entidades governamentais ou de caráter público;","b) para a retificação de dados, quando não se prefira fazê-lo por processo sigiloso, judicial ou administrativo;","LXXIII - qualquer cidadão é parte legítima para propor ação popular que vise a anular ato lesivo ao patrimônio público ou de entidade de que o Estado participe, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural, ficando o autor, salvo comprovada má-fé, isento de custas judiciais e do ônus da sucumbência;","LXXIV - o Estado prestará assistência jurídica integral e gratuita aos que comprovarem insuficiência de recursos;","LXXV - o Estado indenizará o condenado por erro judiciário, assim como o que ficar preso além do tempo fixado na sentença;","LXXVI - são gratuitos para os reconhecidamente pobres, na forma da lei:","a) o registro civil de nascimento;","b) a certidão de óbito;","LXXVII - são gratuitas as ações de habeas corpus e habeas data, e, na forma da lei, os atos necessários ao exercício da cidadania.","LXXVIII - a todos, no âmbito judicial e administrativo, são assegurados a razoável duração do processo e os meios que garantam a celeridade de sua tramitação. (Inciso acrescido pela Emenda Constitucional nº 45, de 2004)","LXXIX - é assegurado, nos termos da lei, o direito à proteção dos dados pessoais, inclusive nos meios digitais. (Inciso acrescido pela Emenda Constitucional nº 115, de 2022)","§ 1º As normas definidoras dos direitos e garantias fundamentais têm aplicação imediata.","§ 2º Os direitos e garantias expressos nesta Constituição não excluem outros decorrentes do regime e dos princípios por ela adotados, ou dos tratados internacionais em que a República Federativa do Brasil seja parte.","§ 3º Os tratados e convenções internacionais sobre direitos humanos que forem aprovados, em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros, serão equivalentes às emendas constitucionais. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)","§ 4º O Brasil se submete à jurisdição de Tribunal Penal Internacional a cuja criação tenha manifestado adesão. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)"],"url":"https://www2.camara.leg.br/legin/fed/consti/1988/constituicao-1988-5-outubro-1988-322142-normaatualizada-pl.html"},{"key":"cpp:157","law":"cpp","ref":"157","label":"CPP — art. 157","paragraphs":["Art. 157. São inadmissíveis, devendo ser desentranhadas do processo, as provas ilícitas, assim entendidas as obtidas em violação a normas constitucionais ou legais. (“Caput” do artigo com redação dada pela Lei nº 11.690, de 9/6/200)","§ 1º São também inadmissíveis as provas derivadas das ilícitas, salvo quando não evidenciado o nexo de causalidade entre umas e outras, ou quando as derivadas puderem ser obtidas por uma fonte independente das primeiras. (Parágrafo acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Considera-se fonte independente aquela que por si só, seguindo os trâmites típicos e de praxe, próprios da investigação ou instrução criminal, seria capaz de conduzir ao fato objeto da prova. (Parágrafo acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º Preclusa a decisão de desentranhamento da prova declarada inadmissível, esta será inutilizada por decisão judicial, facultado às partes acompanhar o incidente. (Parágrafo acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 4º (VETADO na Lei nº 11.690, de 9/6/2008)","§ 5º O juiz que conhecer do conteúdo da prova declarada inadmissível não poderá proferir a sentença ou acórdão.","(Parágrafo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação) (Parágrafo declarado inconstitucional, em controle concentrado, pelo Supremo Tribunal Federal, pelas ADIs nºs 6.298, 6.299, 6.300 e 6.305, cuja Decisão foi publicada no DOU de 4/9/2023)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:158-A","law":"cpp","ref":"158-A","label":"CPP — art. 158-A","paragraphs":["Art. 158-A. Considera-se cadeia de custódia o conjunto de todos os procedimentos utilizados para manter e documentar a história cronológica do vestígio coletado em locais ou em vítimas de crimes, para rastrear sua posse e manuseio a partir de seu reconhecimento até o descarte.","§ 1º O início da cadeia de custódia dá-se com a preservação do local de crime ou com procedimentos policiais ou periciais nos quais seja detectada a existência de vestígio.","§ 2º O agente público que reconhecer um elemento como de potencial interesse para a produção da prova pericial fica responsável por sua preservação.","§ 3º Vestígio é todo objeto ou material bruto, visível ou latente, constatado ou recolhido, que se relaciona à infração penal. (Artigo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:158-B","law":"cpp","ref":"158-B","label":"CPP — art. 158-B","paragraphs":["Art. 158-B. A cadeia de custódia compreende o rastreamento do vestígio nas seguintes etapas:","I - reconhecimento: ato de distinguir um elemento como de potencial interesse para a produção da prova pericial;","II - isolamento: ato de evitar que se altere o estado das coisas, devendo isolar e preservar o ambiente imediato, mediato e relacionado aos vestígios e local de crime;","III - fixação: descrição detalhada do vestígio conforme se encontra no local de crime ou no corpo de delito, e a sua posição na área de exames, podendo ser ilustrada por fotografias, filmagens ou croqui, sendo indispensável a sua descrição no laudo pericial produzido pelo perito responsável pelo atendimento;","IV - coleta: ato de recolher o vestígio que será submetido à análise pericial, respeitando suas características e natureza;","V - acondicionamento: procedimento por meio do qual cada vestígio coletado é embalado de forma individualizada, de acordo com suas características físicas, químicas e biológicas, para posterior análise, com anotação da data, hora e nome de quem realizou a coleta e o acondicionamento;","VI - transporte: ato de transferir o vestígio de um local para o outro, utilizando as condições adequadas (embalagens, veículos, temperatura, entre outras), de modo a garantir a manutenção de suas características originais, bem como o controle de sua posse;","VII - recebimento: ato formal de transferência da posse do vestígio, que deve ser documentado com, no mínimo, informações referentes ao número de procedimento e unidade de polícia judiciária relacionada, local de origem, nome de quem transportou o vestígio, código de rastreamento, natureza do exame, tipo do vestígio, protocolo, assinatura e identificação de quem o recebeu;","VIII - processamento: exame pericial em si, manipulação do vestígio de acordo com a metodologia adequada às suas características biológicas, físicas e químicas, a fim de se obter o resultado desejado, que deverá ser formalizado em laudo produzido por perito;","IX - armazenamento: procedimento referente à guarda, em condições adequadas, do material a ser processado, guardado para realização de contraperícia, descartado ou transportado, com vinculação ao número do laudo correspondente;","X - descarte: procedimento referente à liberação do vestígio, respeitando a legislação vigente e, quando pertinente, mediante autorização judicial. (Artigo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:158-C","law":"cpp","ref":"158-C","label":"CPP — art. 158-C","paragraphs":["Art. 158-C. A coleta dos vestígios deverá ser realizada preferencialmente por perito oficial, que dará o encaminhamento necessário para a central de custódia, mesmo quando for necessária a realização de exames complementares.","§ 1º Todos vestígios coletados no decurso do inquérito ou processo devem ser tratados como descrito nesta Lei, ficando órgão central de perícia oficial de natureza criminal responsável por detalhar a forma do seu cumprimento.","§ 2º É proibida a entrada em locais isolados bem como a remoção de quaisquer vestígios de locais de crime antes da liberação por parte do perito responsável, sendo tipificada como fraude processual a sua realização. (Artigo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:158-D","law":"cpp","ref":"158-D","label":"CPP — art. 158-D","paragraphs":["Art. 158-D. O recipiente para acondicionamento do vestígio será determinado pela natureza do material.","§ 1º Todos os recipientes deverão ser selados com lacres, com numeração individualizada, de forma a garantir a inviolabilidade e a idoneidade do vestígio durante o transporte.","§ 2º O recipiente deverá individualizar o vestígio, preservar suas características, impedir contaminação e vazamento, ter grau de resistência adequado e espaço para registro de informações sobre seu conteúdo.","§ 3º O recipiente só poderá ser aberto pelo perito que vai proceder à análise e, motivadamente, por pessoa autorizada.","§ 4º Após cada rompimento de lacre, deve se fazer constar na ficha de acompanhamento de vestígio o nome e a matrícula do responsável, a data, o local, a finalidade, bem como as informações referentes ao novo lacre utilizado.","§ 5º O lacre rompido deverá ser acondicionado no interior do novo recipiente. (Artigo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:158-E","law":"cpp","ref":"158-E","label":"CPP — art. 158-E","paragraphs":["Art. 158-E. Todos os Institutos de Criminalística deverão ter uma central de custódia destinada à guarda e controle dos vestígios, e sua gestão deve ser vinculada diretamente ao órgão central de perícia oficial de natureza criminal.","§ 1º Toda central de custódia deve possuir os serviços de protocolo, com local para conferência, recepção, devolução de materiais e documentos, possibilitando a seleção, a classificação e a distribuição de materiais, devendo ser um espaço seguro e apresentar condições ambientais que não interfiram nas características do vestígio.","§ 2º Na central de custódia, a entrada e a saída de vestígio deverão ser protocoladas, consignando-se informações sobre a ocorrência no inquérito que a eles se relacionam.","§ 3º Todas as pessoas que tiverem acesso ao vestígio armazenado deverão ser identificadas e deverão ser registradas a data e a hora do acesso.","§ 4º Por ocasião da tramitação do vestígio armazenado, todas as ações deverão ser registradas, consignando-se a identificação do responsável pela tramitação, a destinação, a data e horário da ação. (Artigo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:158-F","law":"cpp","ref":"158-F","label":"CPP — art. 158-F","paragraphs":["Art. 158-F. Após a realização da perícia, o material deverá ser devolvido à central de custódia, devendo nela permanecer.","Parágrafo único. Caso a central de custódia não possua espaço ou condições de armazenar determinado material, deverá a autoridade policial ou judiciária determinar as condições de depósito do referido material em local diverso, mediante requerimento do diretor do órgão central de perícia oficial de natureza criminal. (Artigo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:158","law":"cpp","ref":"158","label":"CPP — art. 158","paragraphs":["Art. 158. Quando a infração deixar vestígios, será indispensável o exame de corpo de delito, direto ou indireto, não podendo supri-lo a confissão do acusado.","Parágrafo único. Dar-se-á prioridade à realização do exame de corpo de delito quando se tratar de crime que envolva:","I - violência doméstica e familiar contra mulher;","II - violência contra criança, adolescente, idoso ou pessoa com deficiência. (Parágrafo único acrescido pela Lei nº 13.721, de 2/10/2018)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:159","law":"cpp","ref":"159","label":"CPP — art. 159","paragraphs":["Art. 159. O exame de corpo de delito e outras perícias serão realizados por perito oficial, portador de diploma de curso superior. (“Caput” do artigo com redação dada pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Na falta de perito oficial, o exame será realizado por 2 (duas) pessoas idôneas, portadoras de diploma de curso superior preferencialmente na área específica, dentre as que tiverem habilitação técnica relacionada com a natureza do exame. (Parágrafo com redação dada pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Os peritos não oficiais prestarão o compromisso de bem e fielmente desempenhar o encargo. (Parágrafo com redação dada pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º Serão facultadas ao Ministério Público, ao assistente de acusação, ao ofendido, ao querelante e ao acusado a formulação de quesitos e indicação de assistente técnico. (Parágrafo acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 4º O assistente técnico atuará a partir de sua admissão pelo juiz e após a conclusão dos exames e elaboração do laudo pelos peritos oficiais, sendo as partes intimadas desta decisão. (Parágrafo acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 5º Durante o curso do processo judicial, é permitido às partes, quanto à perícia:","I - requerer a oitiva dos peritos para esclarecerem a prova ou para responderem a quesitos, desde que o mandado de intimação e os quesitos ou questões a serem esclarecidas sejam encaminhados com antecedência mínima de 10 (dez) dias, podendo apresentar as respostas em laudo complementar;","II - indicar assistentes técnicos que poderão apresentar pareceres em prazo a ser fixado pelo juiz ou ser inquiridos em audiência. (Parágrafo acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 6º Havendo requerimento das partes, o material probatório que serviu de base à perícia será disponibilizado no ambiente do órgão oficial, que manterá sempre sua guarda, e na presença de perito oficial, para exame pelos assistentes, salvo se for impossível a sua conservação. (Parágrafo acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 7º Tratando-se de perícia complexa que abranja mais de uma área de conhecimento especializado, poder-se-á designar a atuação de mais de um perito oficial, e a parte indicar mais de um assistente técnico. (Parágrafo acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:160","law":"cpp","ref":"160","label":"CPP — art. 160","paragraphs":["Art. 160. Os peritos elaborarão o laudo pericial, onde descreverão minuciosamente o que examinarem, e responderão aos quesitos formulados.","Parágrafo único. O laudo pericial será elaborado no prazo máximo de 10 dias, podendo este prazo ser prorrogado, em casos excepcionais, a requerimento dos peritos. (Artigo com redação dada pela Lei nº 8.862, de 28/3/1994)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:182","law":"cpp","ref":"182","label":"CPP — art. 182","paragraphs":["Art. 182. O juiz não ficará adstrito ao laudo, podendo aceitá-lo ou rejeitá-lo, no todo ou em parte."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:167","law":"cpp","ref":"167","label":"CPP — art. 167","paragraphs":["Art. 167. Não sendo possível o exame de corpo de delito, por haverem desaparecido os vestígios, a prova testemunhal poderá suprir-lhe a falta."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:162","law":"cpp","ref":"162","label":"CPP — art. 162","paragraphs":["Art. 162. A autópsia será feita pelo menos seis horas depois do óbito, salvo se os peritos, pela evidência dos sinais de morte, julgarem que possa ser feita antes daquele prazo, o que declararão no auto.","Parágrafo único. Nos casos de morte violenta, bastará o simples exame externo do cadáver, quando não houver infração penal que apurar, ou quando as lesões externas permitirem precisar a causa da morte e não houver necessidade de exame interno para a verificação de alguma circunstância relevante."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cp:129","law":"cp","ref":"129","label":"Código Penal — art. 129","paragraphs":["Art. 129. Ofender a integridade corporal ou a saúde de outrem:","Pena - detenção, de três meses a um ano.","Lesão corporal de natureza grave","§ 1º Se resulta:","I - Incapacidade para as ocupações habituais, por mais de trinta dias;","II - perigo de vida;","III - debilidade permanente de membro, sentido ou função;","IV - aceleração de parto:","Pena - reclusão, de um a cinco anos.","§ 2º Se resulta:","I - Incapacidade permanente para o trabalho;","II - enfermidade incurável;","III- perda ou inutilização de membro, sentido ou função; (Retificado no DOU de 3/1/1941)","IV - deformidade permanente;","V - aborto:","Pena - reclusão, de dois a oito anos.","Lesão corporal seguida de morte","§ 3º Se resulta morte e as circunstâncias evidenciam que o agente não quis o resultado, nem assumiu o risco de produzi-lo:","Pena - reclusão, de quatro a doze anos.","§ 3º-A. No crime previsto no § 3º deste artigo, se cometido no contexto da atuação ou para a consecução das condutas previstas no art. 2º da lei que institui o marco legal do combate ao crime organizado no Brasil:","Pena - reclusão, de 20 (vinte) a 40 (quarenta) anos. (Parágrafo acrescido pela Lei nº 15.358, de 24/3/2026)","Diminuição de pena","§ 4º Se o agente comete o crime impelido por motivo de relevante valor social ou moral ou sob o domínio de violenta emoção, logo em seguida a injusta provocação da vítima, o juiz pode reduzir a pena de um sexto a um terço.","Substituição da pena","§ 5º O juiz, não sendo graves as lesões, pode ainda substituir a pena de detenção pela de multa:","I - se ocorre qualquer das hipóteses do parágrafo anterior;","II - se as lesões são recíprocas.","Lesão corporal culposa","§ 6º Se a lesão é culposa:","Pena - detenção, de dois meses a um ano.","Aumento de pena","§ 7º Aumenta-se a pena de 1/3 (um terço) se ocorrer qualquer das hipóteses dos §§ 4º e 6º do art. 121 deste Código. (Parágrafo com redação dada pela Lei nº 12.720, de 27/9/2012)","§ 8º Aplica-se à lesão culposa o disposto no § 5º do art. 121. (Parágrafo acrescido pela Lei nº 6.416, de 24/5/1977, e com redação dada pela Lei nº 8.069, de 13/7/1990, publicada no DOU de 16/7/1990, em vigor 90 dias após a publicação","§ 8º-A. Com exceção do disposto no § 3º-A deste artigo, aumenta-se a pena em 2/3 (dois terços) se a lesão é praticada por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, no contexto da atuação ou para a consecução das condutas previstas no art. 2º da lei que institui o marco legal do combate ao crime organizado no Brasil. (Parágrafo acrescido pela Lei nº 15.358, de 24/3/2026)","Violência Doméstica (Nome jurídico acrescido pela Lei nº 10.886, de 17/7/2004)","§ 9º Se a lesão for praticada contra ascendente, descendente, irmão, cônjuge ou companheiro, pessoa com relação de trabalho doméstico ou com quem conviva ou tenha convivido, ou, ainda, prevalecendo-se o agente das relações domésticas, de trabalho doméstico, de coabitação ou de hospitalidade: (Parágrafo acrescido pela Lei nº 10.886, de 17/7/2004, e com redação dada pela Lei nº 15.455, de 1º/7/2026)","Pena - reclusão, de 2 (dois) a 5 (cinco) anos. (Pena acrescida pela Lei nº 10.886, de 17/7/2004, e com redação dada pela Lei nº 14.994, de 9/10/2024)","§ 10. Nos casos previstos nos §§ 1º a 3º deste artigo, se as circunstâncias são as indicadas no § 9º deste artigo, aumenta-se a pena em 1/3 (um terço). (Parágrafo acrescido pela Lei nº 10.886, de 17/7/2004)","§ 11. Na hipótese do § 9º deste artigo, a pena será aumentada de um terço se o crime for cometido contra pessoa portadora de deficiência. (Parágrafo acrescido pela Lei nº 11.340, de 7/8/2006, publicada no DOU de 8/8/2006, em vigor 45 dias após a publicação)","§ 12. Aumenta-se a pena de: (Parágrafo acrescido pela Lei nº 13.142, de 6/7/2015, com redação dada pela Lei nº 15.159, de 3/7/2025)","I - 1/3 (um terço) a 2/3 (dois terços) se a lesão dolosa for praticada: (Inciso acrescido pela Lei nº 15.134, de 6/5/2025, com redação dada pela Lei nº 15.159, de 3/7/2025)","a) contra autoridade ou agente descrito nos arts. 142 e 144 da Constituição Federal ou integrantes do sistema prisional ou da Força Nacional de Segurança Pública, no exercício da função ou em decorrência dela, ou contra seu cônjuge, companheiro ou parente consanguíneo até terceiro grau, em razão dessa condição; (Alínea acrescida pela Lei nº 15.159, de 3/7/2025)","b) contra membro do Poder Judiciário, do Ministério Público, da Defensoria Pública ou da Advocacia Pública, de que tratam os arts. 131 e 132 da Constituição Federal, ou oficial de justiça, no exercício da função ou em decorrência dela, ou contra seu cônjuge, companheiro ou parente, inclusive por afinidade, até o terceiro grau, em razão dessa condição; ou (Alínea acrescida pela Lei nº 15.159, de 3/7/2025)","c) nas dependências de instituição de ensino; (Alínea acrescida pela Lei nº 15.159, de 3/7/2025)","II - 2/3 (dois terços) ao dobro se a lesão dolosa for praticada nas dependências de instituição de ensino e: (Inciso acrescido pela Lei nº 15.134, de 6/5/2025, com redação dada pela Lei nº 15.159, de 3/7/2025)","a) a vítima for pessoa com deficiência ou com doença que acarrete condição limitante ou de vulnerabilidade física ou mental; ou (Alínea acrescida pela Lei nº 15.159, de 3/7/2025)","b) o autor for ascendente, padrasto ou madrasta, tio, irmão, cônjuge, companheiro, tutor, curador, preceptor ou empregador da vítima ou por qualquer outro título tiver autoridade sobre ela ou, ainda, for professor ou funcionário da instituição de ensino. (Alínea acrescida pela Lei nº 15.159, de 3/7/2025)","§ 13. Se a lesão é praticada contra a mulher, por razões da condição do sexo feminino, nos termos do § 1º do art. 121-A deste Código:","Pena - reclusão, de 2 (dois) a 5 (cinco) anos (Parágrafo acrescido pela Lei nº 14.188, de 28/7/2021, e com redação dada pela Lei nº 14.994, de 9/10/2024)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html"},{"key":"cpp:168","law":"cpp","ref":"168","label":"CPP — art. 168","paragraphs":["Art. 168. Em caso de lesões corporais, se o primeiro exame pericial tiver sido incompleto, proceder-se-á a exame complementar por determinação da autoridade policial ou judiciária, de ofício, ou a requerimento do Ministério Público, do ofendido ou do acusado, ou de seu defensor.","§ 1º No exame complementar, os peritos terão presente o auto de corpo de delito, a fim de suprir-lhe a deficiência ou retificá-lo.","§ 2º Se o exame tiver por fim precisar a classificação do delito no art. 129, § 1º, I, do Código Penal, deverá ser feito logo que decorra o prazo de 30 dias, contado da data do crime.","§ 3º A falta de exame complementar poderá ser suprida pela prova testemunhal."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:300-A","law":"cpp","ref":"300-A","label":"CPP — art. 300-A","paragraphs":["Art. 300-A. O investigado por crimes contra a dignidade sexual, quando preso cautelarmente, e o condenado pelos mesmos crimes deverão ser submetidos obrigatoriamente à identificação do perfil genético, mediante extração de DNA (ácido desoxirribonucleico), por técnica adequada e indolor, por ocasião do ingresso no estabelecimento prisional. (Artigo acrescido pela Lei nº 15.280, de 5/12/2025)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:310-A","law":"cpp","ref":"310-A","label":"CPP — art. 310-A","paragraphs":["Art. 310-A. No caso de prisão em flagrante por crime praticado com violência ou grave ameaça contra a pessoa, por crime contra a dignidade sexual ou por crime praticado por agente em relação ao qual existam elementos probatórios que indiquem integrar organização criminosa que utilize ou tenha à sua disposição armas de fogo ou em relação ao qual seja imputada a prática de crime previsto no art.","1º da Lei nº 8.072, de 25 de julho de 1990 (Lei dos Crimes Hediondos), o Ministério Público ou a autoridade policial deverá requerer ao juiz a coleta de material biológico para obtenção e armazenamento do perfil genético do custodiado, na forma da Lei nº 12.037, de 1º de outubro de 2009.","§ 1º A coleta de material biológico para a obtenção do perfil genético deverá ser feita, preferencialmente, na própria audiência de custódia ou no prazo de 10 (dez) dias, contado de sua realização.","§ 2º A coleta de material biológico será realizada por agente público treinado e respeitará os procedimentos de cadeia de custódia definidos pela legislação em vigor e complementados pelo órgão de perícia oficial de natureza criminal. (Artigo acrescido pela Lei nº 15.272, de 26/11/2025)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"lep:9-A","law":"lep","ref":"9-A","label":"LEP — art. 9-A","paragraphs":["Art. 9º-A. O condenado à pena de reclusão em regime inicial fechado será submetido obrigatoriamente à identificação do perfil genético, mediante extração de DNA (ácido desoxirribonucleico), por técnica adequada e indolor, por ocasião do ingresso no estabelecimento prisional. (“Caput” do artigo acrescido pela Lei nº 12.654, de 28/5/2012, e com redação dada pela Lei nº 15.295, de 19/12/2025, em vigor 30 dias após a publicação)","§ 1º A identificação do perfil genético será armazenada em banco de dados sigiloso, conforme regulamento a ser expedido pelo Poder Executivo. (Parágrafo acrescido pela Lei nº 12.654, de 28/5/2012, publicada no DOU de 29/5/2012, em vigor 180 dias após a publicação)","§ 1º-A. A regulamentação deverá fazer constar garantias mínimas de proteção de dados genéticos, observando as melhores práticas da genética forense. (Parágrafo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","§ 2º A autoridade policial, federal ou estadual, poderá requerer ao juiz competente, no caso de inquérito instaurado, o acesso ao banco de dados de identificação de perfil genético. (Parágrafo acrescido pela Lei nº 12.654, de 28/5/2012, publicada no DOU de 29/5/2012, em vigor 180 dias após a publicação)","§ 3º Deve ser viabilizado ao titular de dados genéticos o acesso aos seus dados constantes nos bancos de perfis genéticos, bem como a todos os documentos da cadeia de custódia que gerou esse dado, de maneira que possa ser contraditado pela defesa. (Parágrafo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","§ 4º O condenado pelos crimes previstos no caput deste artigo que não tiver sido submetido à identificação do perfil genético por ocasião do ingresso no estabelecimento prisional deverá ser submetido ao procedimento durante o cumprimento da pena. (Parágrafo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","§ 5º A amostra biológica coletada só poderá ser utilizada para o único e exclusivo fim de permitir a identificação pelo perfil genético, não estando autorizadas as práticas de fenotipagem genética. (Parágrafo vetado pelo Presidente da República na Lei nº 13.964, de 24/12/2019, mantido pelo Congresso Nacional e publicado no DOU de 30/4/2021, e com redação dada pela Lei nº 15.295, de 19/12/2025, em vigor 30 dias após a publicação)","§ 6º Uma vez identificado o perfil genético, a amostra biológica recolhida nos termos do caput deste artigo deverá ser correta e imediatamente descartada, guardando-se material suficiente para a eventualidade de nova perícia, nos termos do regulamento, vedada a sua utilização para qualquer outro fim.","(Parágrafo vetado pelo Presidente da República na Lei nº 13.964, de 24/12/2019, mantido pelo Congresso Nacional e publicado no DOU de 30/4/2021, e com redação dada pela Lei nº 15.295, de 19/12/2025, em vigor 30 dias após a publicação)","§ 7º A coleta da amostra biológica será realizada por agente público treinado e respeitará os procedimentos de cadeia de custódia definidos pela legislação em vigor e complementados pelo órgão de perícia oficial de natureza criminal. (Parágrafo vetado pelo Presidente da República na Lei nº 13.964, de 24/12/2019, mantido pelo Congresso Nacional e publicado no DOU de 30/4/2021, e com redação dada pela Lei nº 15.295, de 19/12/2025, em vigor 30 dias após a publicação)","§ 8º Constitui falta grave a recusa do condenado em submeter-se ao procedimento de identificação do perfil genético. (Parágrafo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","§ 9º A elaboração do laudo da amostra biológica coletada nos termos do § 7º será realizada por perito oficial. (Parágrafo acrescido pela Lei nº 15.295, de 19/12/2025, em vigor 30 dias após a publicação)","§ 10. Nos casos dos crimes hediondos e equiparados, o processamento dos vestígios biológicos coletados em locais de crime e corpos de delito e a inclusão dos respectivos perfis genéticos no banco deverão ser realizados, se possível, em até 30 (trinta) dias contados da recepção da amostra pelo laboratório de DNA. (Parágrafo acrescido pela Lei nº 15.295, de 19/12/2025, em vigor 30 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7210-11-julho-1984-356938-normaatualizada-pl.html"},{"key":"cpp:185","law":"cpp","ref":"185","label":"CPP — art. 185","paragraphs":["Art. 185. O acusado que comparecer perante a autoridade judiciária, no curso do processo penal, será qualificado e interrogado na presença de seu defensor, constituído ou nomeado. (“Caput” do artigo com redação dada pela Lei nº 10.792, de 1º/12/2003)","§ 1º O interrogatório do réu preso será realizado, em sala própria, no estabelecimento em que estiver recolhido, desde que estejam garantidas a segurança do juiz, do membro do Ministério Público e dos auxiliares bem como a presença do defensor e a publicidade do ato. (Parágrafo acrescido pela Lei nº 10.792, de 1º/12/2003, e com nova redação dada pela Lei nº 11.900, de 8/1/2009)","§ 2º Excepcionalmente, o juiz, por decisão fundamentada, de ofício ou a requerimento das partes, poderá realizar o interrogatório do réu preso por sistema de videoconferência ou outro recurso tecnológico de transmissão de sons e imagens em tempo real, desde que a medida seja necessária para atender a uma das seguintes finalidades: (“Caput” do parágrafo acrescido pela Lei nº 10.792, de 1º/12/2003, e com nova redação dada pela Lei nº 11.900, de 8/1/2009)","I - prevenir risco à segurança pública, quando exista fundada suspeita de que o preso integre organização criminosa ou de que, por outra razão, possa fugir durante o deslocamento; (Inciso acrescido pela Lei nº 11.900, de 8/1/2009)","II - viabilizar a participação do réu no referido ato processual, quando haja relevante dificuldade para seu comparecimento em juízo, por enfermidade ou outra circunstância pessoal; (Inciso acrescido pela Lei nº 11.900, de 8/1/2009)","III - impedir a influência do réu no ânimo de testemunha ou da vítima, desde que não seja possível colher o depoimento destas por videoconferência, nos termos do art. 217 deste Código; (Inciso acrescido pela Lei nº 11.900, de 8/1/2009)","IV - responder à gravíssima questão de ordem pública. (Inciso acrescido pela Lei nº 11.900, de 8/1/2009)","§ 3º Da decisão que determinar a realização de interrogatório por videoconferência, as partes serão intimadas com 10 (dez) dias de antecedência. (Parágrafo acrescido pela Lei nº 11.900, de 8/1/2009)","§ 4º Antes do interrogatório por videoconferência, o preso poderá acompanhar, pelo mesmo sistema tecnológico, a realização de todos os atos da audiência única de instrução e julgamento de que tratam os arts. 400, 411 e 531 deste Código. (Parágrafo acrescido pela Lei nº 11.900, de 8/1/2009)","§ 5º Em qualquer modalidade de interrogatório, o juiz garantirá ao réu o direito de entrevista prévia e reservada com o seu defensor; se realizado por videoconferência, fica também garantido o acesso a canais telefônicos reservados para comunicação entre o defensor que esteja no presídio e o advogado presente na sala de audiência do Fórum, e entre este e o preso. (Parágrafo acrescido pela Lei nº 11.900, de 8/1/2009)","§ 6º A sala reservada no estabelecimento prisional para a realização de atos processuais por sistema de videoconferência será fiscalizada pelos corregedores e pelo juiz de cada causa, como também pelo Ministério Público e pela Ordem dos Advogados do Brasil. (Parágrafo acrescido pela Lei nº 11.900, de 8/1/2009)","§ 7º Será requisitada a apresentação do réu preso em juízo nas hipóteses em que o interrogatório não se realizar na forma prevista nos §§ 1º e 2º deste artigo. (Parágrafo acrescido pela Lei nº 11.900, de 8/1/2009)","§ 8º Aplica-se o disposto nos §§ 2º, 3º, 4º e 5º deste artigo, no que couber, à realização de outros atos processuais que dependam da participação de pessoa que esteja presa, como acareação, reconhecimento de pessoas e coisas, e inquirição de testemunha ou tomada de declarações do ofendido. (Parágrafo acrescido pela Lei nº 11.900, de 8/1/2009)","§ 9º Na hipótese do § 8º deste artigo, fica garantido o acompanhamento do ato processual pelo acusado e seu defensor. (Parágrafo acrescido pela Lei nº 11.900, de 8/1/2009)","§ 10. Do interrogatório deverá constar a informação sobre a existência de filhos, respectivas idades e se possuem alguma deficiência e o nome e o contato de eventual responsável pelos cuidados dos filhos, indicado pela pessoa presa. (Parágrafo acrescido pela Lei nº 13.257, de 8/3/2016)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:186","law":"cpp","ref":"186","label":"CPP — art. 186","paragraphs":["Art. 186. Depois de devidamente qualificado e cientificado do inteiro teor da acusação, o acusado será informado pelo juiz, antes de iniciar o interrogatório, do seu direito de permanecer calado e de não responder perguntas que lhe forem formuladas. (“Caput” do artigo com redação dada pela Lei nº 10.792, de 1º/12/2003)","Parágrafo único. O silêncio, que não importará em confissão, não poderá ser interpretado em prejuízo da defesa. (Parágrafo único acrescido pela Lei nº 10.792, de 1º/12/2003)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:187","law":"cpp","ref":"187","label":"CPP — art. 187","paragraphs":["Art. 187. O interrogatório será constituído de duas partes: sobre a pessoa do acusado e sobre os fatos. (“Caput” do artigo com redação dada pela Lei nº 10.792, de 1º/12/2003)","§ 1º Na primeira parte o interrogando será perguntado sobre a residência, meios de vida ou profissão, oportunidades sociais, lugar onde exerce a sua atividade, vida pregressa, notadamente se foi preso ou processado alguma vez e, em caso afirmativo, qual o juízo do processo, se houve suspensão condicional ou condenação, qual a pena imposta, se a cumpriu e outros dados familiares e sociais. (Parágrafo acrescido pela Lei nº 10.792, de 1º/12/2003)","§ 2º Na segunda parte será perguntado sobre:","I - ser verdadeira a acusação que lhe é feita;","II - não sendo verdadeira a acusação, se tem algum motivo particular a que atribuí-la, se conhece a pessoa ou pessoas a quem deva ser imputada a prática do crime, e quais sejam, e se com elas esteve antes da prática da infração ou depois dela;","III - onde estava ao tempo em que foi cometida a infração e se teve notícia desta;","IV - as provas já apuradas;","V - se conhece as vítimas e testemunhas já inquiridas ou por inquirir, e desde quando, e se tem o que alegar contra elas;","VI - se conhece o instrumento com que foi praticada a infração, ou qualquer objeto que com esta se relacione e tenha sido apreendido;","VII - todos os demais fatos e pormenores que conduzam à elucidação dos antecedentes e circunstâncias da infração;","VIII - se tem algo mais a alegar em sua defesa. (Parágrafo acrescido pela Lei nº 10.792, de 1º/12/2003)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:188","law":"cpp","ref":"188","label":"CPP — art. 188","paragraphs":["Art. 188. Após proceder ao interrogatório, o juiz indagará das partes se restou algum fato para ser esclarecido, formulando as perguntas correspondentes se o entender pertinente e relevante. (Artigo com redação dada pela Lei nº 10.792, de 1º/12/2003)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:189","law":"cpp","ref":"189","label":"CPP — art. 189","paragraphs":["Art. 189. Se o interrogando negar a acusação, no todo ou em parte, poderá prestar esclarecimentos e indicar provas. (Artigo com redação dada pela Lei nº 10.792, de 1º/12/2003)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:190","law":"cpp","ref":"190","label":"CPP — art. 190","paragraphs":["Art. 190. Se confessar a autoria, será perguntado sobre os motivos e circunstâncias do fato e se outras pessoas concorreram para a infração, e quais sejam. (Artigo com redação dada pela Lei nº 10.792, de 1º/12/2003)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:191","law":"cpp","ref":"191","label":"CPP — art. 191","paragraphs":["Art. 191. Havendo mais de um acusado, serão interrogados separadamente. (Artigo com redação dada pela Lei nº 10.792, de 1º/12/2003)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:192","law":"cpp","ref":"192","label":"CPP — art. 192","paragraphs":["Art. 192. O interrogatório do mudo, do surdo ou do surdo-mudo será feito pela forma seguinte:","I - ao surdo serão apresentadas por escrito as perguntas, que ele responderá oralmente;","II - ao mudo as perguntas serão feitas oralmente, respondendo-as por escrito;","III - ao surdo-mudo as perguntas serão formuladas por escrito e do mesmo modo dará as respostas.","Parágrafo único. Caso o interrogando não saiba ler ou escrever, intervirá no ato, como intérprete e sob compromisso, pessoa habilitada a entendê-lo. (Artigo com redação dada pela Lei nº 10.792, de 1º/12/2003)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:193","law":"cpp","ref":"193","label":"CPP — art. 193","paragraphs":["Art. 193. Quando o interrogando não falar a língua nacional, o interrogatório será feito por meio de intérprete. (Artigo com redação dada pela Lei nº 10.792, de 1º/12/2003)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:194","law":"cpp","ref":"194","label":"CPP — art. 194","paragraphs":["Art. 194. (Revogado pela Lei nº 10.792, de 1º/12/2003)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:195","law":"cpp","ref":"195","label":"CPP — art. 195","paragraphs":["Art. 195. Se o interrogado não souber escrever, não puder ou não quiser assinar, tal fato será consignado no termo. (Artigo com redação dada pela Lei nº 10.792, de 1º/12/2003)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:196","law":"cpp","ref":"196","label":"CPP — art. 196","paragraphs":["Art. 196. A todo tempo o juiz poderá proceder a novo interrogatório de ofício ou a pedido fundamentado de qualquer das partes. (Artigo com redação dada pela Lei nº 10.792, de 1º/12/2003)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:197","law":"cpp","ref":"197","label":"CPP — art. 197","paragraphs":["Art. 197. O valor da confissão se aferirá pelos critérios adotados para os outros elementos de prova, e para a sua apreciação o juiz deverá confrontá-la com as demais provas do processo, verificando se entre ela e estas existe compatibilidade ou concordância."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:198","law":"cpp","ref":"198","label":"CPP — art. 198","paragraphs":["Art. 198. O silêncio do acusado não importará confissão, mas poderá constituir elemento para a formação do convencimento do juiz."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:199","law":"cpp","ref":"199","label":"CPP — art. 199","paragraphs":["Art. 199. A confissão, quando feita fora do interrogatório, será tomada por termo nos autos, observado o disposto no art. 195."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:200","law":"cpp","ref":"200","label":"CPP — art. 200","paragraphs":["Art. 200. A confissão será divisível e retratável, sem prejuízo do livre convencimento do juiz, fundado no exame das provas em conjunto."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:201","law":"cpp","ref":"201","label":"CPP — art. 201","paragraphs":["Art. 201. Sempre que possível, o ofendido será qualificado e perguntado sobre as circunstâncias da infração, quem seja ou presuma ser o seu autor, as provas que possa indicar, tomando-se por termo as suas declarações. (“Caput” do artigo com redação dada pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Se, intimado para esse fim, deixar de comparecer sem motivo justo, o ofendido poderá ser conduzido à presença da autoridade. (Parágrafo único transformado em § 1º pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º O ofendido será comunicado dos atos processuais relativos ao ingresso e à saída do acusado da prisão, à designação de data para audiência e à sentença e respectivos acórdãos que a mantenham ou modifiquem. (Parágrafo acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º As comunicações ao ofendido deverão ser feitas no endereço por ele indicado, admitindo-se, por opção do ofendido, o uso de meio eletrônico. (Parágrafo acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 4º Antes do início da audiência e durante a sua realização, será reservado espaço separado para o ofendido. (Parágrafo acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 5º Se o juiz entender necessário, poderá encaminhar o ofendido para atendimento multidisciplinar, especialmente nas áreas psicossocial, de assistência jurídica e de saúde, a expensas do ofensor ou do Estado. (Parágrafo acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 6º O juiz tomará as providências necessárias à preservação da intimidade, vida privada, honra e imagem do ofendido, podendo, inclusive, determinar o segredo de justiça em relação aos dados, depoimentos e outras informações constantes dos autos a seu respeito para evitar sua exposição aos meios de comunicação. (Parágrafo acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:202","law":"cpp","ref":"202","label":"CPP — art. 202","paragraphs":["Art. 202. Toda pessoa poderá ser testemunha."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:203","law":"cpp","ref":"203","label":"CPP — art. 203","paragraphs":["Art. 203. A testemunha fará, sob palavra de honra, a promessa de dizer a verdade do que souber e lhe for perguntado, devendo declarar seu nome, sua idade, seu estado e sua residência, sua profissão, lugar onde exerce sua atividade, se é parente, e em que grau, de alguma das partes, ou quais suas relações com qualquer delas, e relatar o que souber, explicando sempre as razões de sua ciência ou as circunstâncias pelas quais possa avaliar-se de sua credibilidade."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:204","law":"cpp","ref":"204","label":"CPP — art. 204","paragraphs":["Art. 204. O depoimento será prestado oralmente, não sendo permitido à testemunha trazê-lo por escrito.","Parágrafo único. Não será vedada à testemunha, entretanto, breve consulta a apontamentos."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:205","law":"cpp","ref":"205","label":"CPP — art. 205","paragraphs":["Art. 205. Se ocorrer dúvida sobre a identidade da testemunha, o juiz procederá à verificação pelos meios ao seu alcance, podendo, entretanto, tomar-lhe o depoimento desde logo."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:206","law":"cpp","ref":"206","label":"CPP — art. 206","paragraphs":["Art. 206. A testemunha não poderá eximir-se da obrigação de depor. Poderão, entretanto, recusar-se a fazê-lo o ascendente ou descendente, o afim em linha reta, o cônjuge, ainda que desquitado, o irmão e o pai, a mãe, ou o filho adotivo do acusado, salvo quando não for possível, por outro modo, obter-se ou integrar-se a prova do fato e de suas circunstâncias."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:207","law":"cpp","ref":"207","label":"CPP — art. 207","paragraphs":["Art. 207. São proibidas de depor as pessoas que, em razão de função, ministério, ofício ou profissão, devam guardar segredo, salvo se, desobrigadas pela parte interessada, quiserem dar o seu testemunho."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:208","law":"cpp","ref":"208","label":"CPP — art. 208","paragraphs":["Art. 208. Não se deferirá o compromisso a que alude o art. 203 aos doentes e deficientes mentais e aos menores de 14 anos, nem às pessoas a que se refere o art. 206."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:209","law":"cpp","ref":"209","label":"CPP — art. 209","paragraphs":["Art. 209. O juiz, quando julgar necessário, poderá ouvir outras testemunhas, além das indicadas pelas partes.","§ 1º Se ao juiz parecer conveniente, serão ouvidas as pessoas a que as testemunhas se referirem.","§ 2º Não será computada como testemunha a pessoa que nada souber que interesse à decisão da causa."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:210","law":"cpp","ref":"210","label":"CPP — art. 210","paragraphs":["Art. 210. As testemunhas serão inquiridas cada uma de per si, de modo que umas não saibam nem ouçam os depoimentos das outras, devendo o juiz adverti-las das penas cominadas ao falso testemunho. (“Caput” do artigo com redação dada pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Antes do início da audiência e durante a sua realização, serão reservados espaços separados para a garantia da incomunicabilidade das testemunhas. (Parágrafo único acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:211","law":"cpp","ref":"211","label":"CPP — art. 211","paragraphs":["Art. 211. Se o juiz, ao pronunciar sentença final, reconhecer que alguma testemunha fez afirmação falsa, calou ou negou a verdade, remeterá cópia do depoimento à autoridade policial para a instauração de inquérito.","Parágrafo único. Tendo o depoimento sido prestado em plenário de julgamento, o juiz, no caso de proferir decisão na audiência (art. 538, § 2º), o tribunal (art. 561), ou o conselho de sentença, após a votação dos quesitos, poderão fazer apresentar imediatamente a testemunha à autoridade policial."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:212","law":"cpp","ref":"212","label":"CPP — art. 212","paragraphs":["Art. 212. As perguntas serão formuladas pelas partes diretamente à testemunha, não admitindo o juiz aquelas que puderem induzir a resposta, não tiverem relação com a causa ou importarem na repetição de outra já respondida. (“Caput” do artigo com redação dada pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Sobre os pontos não esclarecidos, o juiz poderá complementar a inquirição. (Parágrafo único acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:213","law":"cpp","ref":"213","label":"CPP — art. 213","paragraphs":["Art. 213. O juiz não permitirá que a testemunha manifeste suas apreciações pessoais, salvo quando inseparáveis da narrativa do fato."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:214","law":"cpp","ref":"214","label":"CPP — art. 214","paragraphs":["Art. 214. Antes de iniciado o depoimento, as partes poderão contraditar a testemunha ou argüir circunstâncias ou defeitos, que a tornem suspeita de parcialidade, ou indigna de fé. O juiz fará consignar a contradita ou argüição e a resposta da testemunha, mas só excluirá a testemunha ou não lhe deferirá compromisso nos casos previstos nos arts. 207 e 208."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:215","law":"cpp","ref":"215","label":"CPP — art. 215","paragraphs":["Art. 215. Na redação do depoimento, o juiz deverá cingir-se, tanto quanto possível, às expressões usadas pelas testemunhas, reproduzindo fielmente as suas frases."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:216","law":"cpp","ref":"216","label":"CPP — art. 216","paragraphs":["Art. 216. O depoimento da testemunha será reduzido a termo, assinado por ela, pelo juiz e pelas partes. Se a testemunha não souber assinar, ou não puder fazê-lo, pedirá a alguém que o faça por ela, depois de lido na presença de ambos."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:217","law":"cpp","ref":"217","label":"CPP — art. 217","paragraphs":["Art. 217. Se o juiz verificar que a presença do réu poderá causar humilhação, temor, ou sério constrangimento à testemunha ou ao ofendido, de modo que prejudique a verdade do depoimento, fará a inquirição por videoconferência e, somente na impossibilidade dessa forma, determinará a retirada do réu, prosseguindo na inquirição, com a presença do seu defensor. (“Caput” do artigo com redação dada pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. A adoção de qualquer das medidas previstas no caput deste artigo deverá constar do termo, assim como os motivos que a determinaram. (Parágrafo único acrescido pela Lei nº 11.690, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:218","law":"cpp","ref":"218","label":"CPP — art. 218","paragraphs":["Art. 218. Se, regularmente intimada, a testemunha deixar de comparecer sem motivo justificado, o juiz poderá requisitar à autoridade policial a sua apresentação ou determinar seja conduzida por oficial de justiça, que poderá solicitar o auxílio da força pública."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:219","law":"cpp","ref":"219","label":"CPP — art. 219","paragraphs":["Art. 219. O juiz poderá aplicar à testemunha faltosa a multa prevista no artigo 453, sem prejuízo do processo penal por crime de desobediência, e condená-la ao pagamento das custas da diligência. (Artigo com redação dada pela Lei nº 6.416, de 24/5/1977)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:220","law":"cpp","ref":"220","label":"CPP — art. 220","paragraphs":["Art. 220. As pessoas impossibilitadas, por enfermidade ou por velhice, de comparecer para depor, serão inquiridas onde estiverem."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:221","law":"cpp","ref":"221","label":"CPP — art. 221","paragraphs":["Art. 221.","O Presidente e o Vice-Presidente da República, os Senadores e Deputados Federais, os Ministros de Estado, os Governadores de Estado e Territórios, os Secretários de Estado, os Prefeitos do Distrito Federal e dos Municípios, os Deputados às Assembléias Legislativas Estaduais, os membros do Poder Judiciário, os Ministros e Juízes dos Tribunais de Contas da União, dos Estados, do Distrito Federal, bem como os do Tribunal Marítimo serão inquiridos em local, dia e hora previamente ajustados entre eles e o Juiz.","(“Caput” do artigo com redação dada pela Lei nº 3.653, de 4/11/1959)","§ 1º O Presidente e o Vice-Presidente da República, os Presidentes do Senado Federal, da Câmara dos Deputados e do Supremo Tribunal Federal poderão optar pela prestação de depoimento por escrito, caso em que as perguntas, formuladas pelas partes e deferidas pelo juiz, lhes serão transmitidas por ofício. (Parágrafo com redação dada pela Lei nº 6.416, de 24/5/1977)","§ 2º Os militares deverão ser requisitados à autoridade superior. (Parágrafo com redação dada pela Lei nº 6.416, de 24/5/1977)","§ 3º Aos funcionários públicos aplicar-se-á o disposto no artigo 218, devendo, porém, a expedição do mandado ser imediatamente comunicada ao chefe da repartição em que servirem, com indicação do dia e da hora marcados. (Parágrafo acrescido pela Lei nº 6.416, de 24/5/1977)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:222","law":"cpp","ref":"222","label":"CPP — art. 222","paragraphs":["Art. 222. A testemunha que morar fora da jurisdição do juiz, será inquirida pelo juiz do lugar de sua residência, expedindo-se, para esse fim, carta precatória, com prazo razoável, intimadas as partes.","§ 1º A expedição da precatória não suspenderá a instrução criminal.","§ 2º Findo o prazo marcado, poderá realizar-se o julgamento, mas, a todo tempo, a precatória, uma vez devolvida, será junta aos autos.","§ 3º Na hipótese prevista no caput deste artigo, a oitiva de testemunha poderá ser realizada por meio de videoconferência ou outro recurso tecnológico de transmissão de sons e imagens em tempo real, permitida a presença do defensor e podendo ser realizada, inclusive, durante a realização da audiência de instrução e julgamento. (Parágrafo acrescido pela Lei nº 11.900, de 8/1/2009)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:223","law":"cpp","ref":"223","label":"CPP — art. 223","paragraphs":["Art. 223. Quando a testemunha não conhecer a língua nacional, será nomeado intérprete para traduzir as perguntas e respostas.","Parágrafo único. Tratando-se de mudo, surdo ou surdo-mudo, proceder-se-á na conformidade do art. 192."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:224","law":"cpp","ref":"224","label":"CPP — art. 224","paragraphs":["Art. 224. As testemunhas comunicarão ao juiz, dentro de um ano, qualquer mudança de residência, sujeitando-se, pela simples omissão, às penas do não-comparecimento."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:225","law":"cpp","ref":"225","label":"CPP — art. 225","paragraphs":["Art. 225. Se qualquer testemunha houver de ausentar-se, ou, por enfermidade ou por velhice, inspirar receio de que ao tempo da instrução criminal já não exista, o juiz poderá, de ofício ou a requerimento de qualquer das partes, tomar-lhe antecipadamente o depoimento."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:226","law":"cpp","ref":"226","label":"CPP — art. 226","paragraphs":["Art. 226. Quando houver necessidade de fazer-se o reconhecimento de pessoa, proceder-se-á pela seguinte forma:","I - a pessoa que tiver de fazer o reconhecimento será convidada a descrever a pessoa que deva ser reconhecida;","II - a pessoa, cujo reconhecimento se pretender, será colocada, se possível, ao lado de outras que com ela tiverem qualquer semelhança, convidando-se quem tiver de fazer o reconhecimento a apontá-la;","III - se houver razão para recear que a pessoa chamada para o reconhecimento, por efeito de intimidação ou outra influência, não diga a verdade em face da pessoa que deve ser reconhecida, a autoridade providenciará para que esta não veja aquela;","IV - do ato de reconhecimento lavrar-se-á auto pormenorizado, subscrito pela autoridade, pela pessoa chamada para proceder ao reconhecimento e por duas testemunhas presenciais.","Parágrafo único. O disposto no n. III deste artigo não terá aplicação na fase da instrução criminal ou em plenário de julgamento."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:227","law":"cpp","ref":"227","label":"CPP — art. 227","paragraphs":["Art. 227. No reconhecimento de objeto, proceder-se-á com as cautelas estabelecidas no artigo anterior, no que for aplicável."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:228","law":"cpp","ref":"228","label":"CPP — art. 228","paragraphs":["Art. 228. Se várias forem as pessoas chamadas a efetuar o reconhecimento de pessoa ou de objeto, cada uma fará a prova em separado, evitando-se qualquer comunicação entre elas."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:7","law":"cpp","ref":"7","label":"CPP — art. 7","paragraphs":["Art. 7º Para verificar a possibilidade de haver a infração sido praticada de determinado modo, a autoridade policial poderá proceder à reprodução simulada dos fatos, desde que esta não contrarie a moralidade ou a ordem pública."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:229","law":"cpp","ref":"229","label":"CPP — art. 229","paragraphs":["Art. 229. A acareação será admitida entre acusados, entre acusado e testemunha, entre testemunhas, entre acusado ou testemunha e a pessoa ofendida, e entre as pessoas ofendidas, sempre que divergirem, em suas declarações, sobre fatos ou circunstâncias relevantes.","Parágrafo único. Os acareados serão reperguntados, para que expliquem os pontos de divergência, reduzindo-se a termo o ato de acareação."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:230","law":"cpp","ref":"230","label":"CPP — art. 230","paragraphs":["Art. 230. Se ausente alguma testemunha, cujas declarações divirjam das de outra, que esteja presente, a esta se darão a conhecer os pontos da divergência, consignando-se no auto o que explicar ou observar.","Se subsistir a discordância, expedir-se-á precatória à autoridade do lugar onde resida a testemunha ausente, transcrevendo-se as declarações desta e as da testemunha presente, nos pontos em que divergirem, bem como o texto do referido auto, a fim de que se complete a diligência, ouvindo-se a testemunha ausente, pela mesma forma estabelecida para a testemunha presente. Esta diligência só se realizará quando não importe demora prejudicial ao processo e o juiz a entenda conveniente."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:231","law":"cpp","ref":"231","label":"CPP — art. 231","paragraphs":["Art. 231. Salvo os casos expressos em lei, as partes poderão apresentar documentos em qualquer fase do processo."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:232","law":"cpp","ref":"232","label":"CPP — art. 232","paragraphs":["Art. 232. Consideram-se documentos quaisquer escritos, instrumentos ou papéis, públicos ou particulares.","Parágrafo único. À fotografia do documento, devidamente autenticada, se dará o mesmo valor do original."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:233","law":"cpp","ref":"233","label":"CPP — art. 233","paragraphs":["Art. 233. As cartas particulares, interceptadas ou obtidas por meios criminosos, não serão admitidas em juízo.","Parágrafo único. As cartas poderão ser exibidas em juízo pelo respectivo destinatário, para a defesa de seu direito, ainda que não haja consentimento do signatário."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:234","law":"cpp","ref":"234","label":"CPP — art. 234","paragraphs":["Art. 234. Se o juiz tiver notícia da existência de documento relativo a ponto relevante da acusação ou da defesa, providenciará, independentemente de requerimento de qualquer das partes, para sua juntada aos autos, se possível."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:235","law":"cpp","ref":"235","label":"CPP — art. 235","paragraphs":["Art. 235. A letra e firma dos documentos particulares serão submetidas a exame pericial, quando contestada a sua autenticidade."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:236","law":"cpp","ref":"236","label":"CPP — art. 236","paragraphs":["Art. 236. Os documentos em língua estrangeira, sem prejuízo de sua juntada imediata, serão, se necessário, traduzidos por tradutor público, ou, na falta, por pessoa idônea nomeada pela autoridade."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:237","law":"cpp","ref":"237","label":"CPP — art. 237","paragraphs":["Art. 237. As públicas-formas só terão valor quando conferidas com o original, em presença da autoridade."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:238","law":"cpp","ref":"238","label":"CPP — art. 238","paragraphs":["Art. 238. Os documentos originais, juntos a processo findo, quando não exista motivo relevante que justifique a sua conservação nos autos, poderão, mediante requerimento, e ouvido o Ministério Público, ser entregues à parte que os produziu, ficando traslado nos autos."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:479","law":"cpp","ref":"479","label":"CPP — art. 479","paragraphs":["Art. 479. Durante o julgamento não será permitida a leitura de documento ou a exibição de objeto que não tiver sido juntado aos autos com a antecedência mínima de 3 (três) dias úteis, dando-se ciência à outra parte. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Compreende-se na proibição deste artigo a leitura de jornais ou qualquer outro escrito, bem como a exibição de vídeos, gravações, fotografias, laudos, quadros, croqui ou qualquer outro meio assemelhado, cujo conteúdo versar sobre a matéria de fato submetida à apreciação e julgamento dos jurados. (Parágrafo único acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:239","law":"cpp","ref":"239","label":"CPP — art. 239","paragraphs":["Art. 239. Considera-se indício a circunstância conhecida e provada, que, tendo relação com o fato, autorize, por indução, concluir-se a existência de outra ou outras circunstâncias."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:240","law":"cpp","ref":"240","label":"CPP — art. 240","paragraphs":["Art. 240. A busca será domiciliar ou pessoal.","§ 1º Proceder-se-á à busca domiciliar, quando fundadas razões a autorizarem, para:","a) prender criminosos;","b) apreender coisas achadas ou obtidas por meios criminosos;","c) apreender instrumentos de falsificação ou de contrafação e objetos falsificados ou contrafeitos;","d) apreender armas e munições, instrumentos utilizados na prática de crime ou destinados a fim delituoso;","e) descobrir objetos necessários à prova de infração ou à defesa do réu;","f) apreender cartas, abertas ou não, destinadas ao acusado ou em seu poder, quando haja suspeita de que o conhecimento do seu conteúdo possa ser útil à elucidação do fato;","g) apreender pessoas vítimas de crime;","h) colher qualquer elemento de convicção.","§ 2º Proceder-se-á à busca pessoal quando houver fundada suspeita de que alguém oculte consigo arma proibida ou objetos mencionados nas letras b a f e letra h do parágrafo anterior."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:241","law":"cpp","ref":"241","label":"CPP — art. 241","paragraphs":["Art. 241. Quando a própria autoridade policial ou judiciária não a realizar pessoalmente, a busca domiciliar deverá ser precedida da expedição de mandado."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:242","law":"cpp","ref":"242","label":"CPP — art. 242","paragraphs":["Art. 242. A busca poderá ser determinada de ofício ou a requerimento de qualquer das partes."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:243","law":"cpp","ref":"243","label":"CPP — art. 243","paragraphs":["Art. 243. O mandado de busca deverá:","I - indicar, o mais precisamente possível, a casa em que será realizada a diligência e o nome do respectivo proprietário ou morador; ou, no caso de busca pessoal, o nome da pessoa que terá de sofrê-la ou os sinais que a identifiquem;","II - mencionar o motivo e os fins da diligência;","III - ser subscrito pelo escrivão e assinado pela autoridade que o fizer expedir.","§ 1º Se houver ordem de prisão, constará do próprio texto do mandado de busca.","§ 2º Não será permitida a apreensão de documento em poder do defensor do acusado, salvo quando constituir elemento do corpo de delito."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:244","law":"cpp","ref":"244","label":"CPP — art. 244","paragraphs":["Art. 244. A busca pessoal independerá de mandado, no caso de prisão ou quando houver fundada suspeita de que a pessoa esteja na posse de arma proibida ou de objetos ou papéis que constituam corpo de delito, ou quando a medida for determinada no curso de busca domiciliar."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:245","law":"cpp","ref":"245","label":"CPP — art. 245","paragraphs":["Art. 245. As buscas domiciliares serão executadas de dia, salvo se o morador consentir que se realizem à noite, e, antes de penetrarem na casa, os executores mostrarão e lerão o mandado ao morador, ou a quem o represente, intimando-o, em seguida, a abrir a porta.","§ 1º Se a própria autoridade der a busca, declarará previamente sua qualidade e o objeto da diligência.","§ 2º Em caso de desobediência, será arrombada a porta e forçada a entrada.","§ 3º Recalcitrando o morador, será permitido o emprego de força contra coisas existentes no interior da casa, para o descobrimento do que se procura.","§ 4º Observar-se-á o disposto nos §§ 2º e 3º, quando ausentes os moradores, devendo, neste caso, ser intimado a assistir à diligência qualquer vizinho, se houver e estiver presente.","§ 5º Se é determinada a pessoa ou coisa que se vai procurar, o morador será intimado a mostrá-la.","§ 6º Descoberta a pessoa ou coisa que se procura, será imediatamente apreendida e posta sob custódia da autoridade ou de seus agentes.","§ 7º Finda a diligência, os executores lavrarão auto circunstanciado, assinando-o com duas testemunhas presenciais, sem prejuízo do disposto no § 4º."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:246","law":"cpp","ref":"246","label":"CPP — art. 246","paragraphs":["Art. 246. Aplicar-se-á também o disposto no artigo anterior, quando se tiver de proceder a busca em compartimento habitado ou em aposento ocupado de habitação coletiva ou em compartimento não aberto ao público, onde alguém exercer profissão ou atividade."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:247","law":"cpp","ref":"247","label":"CPP — art. 247","paragraphs":["Art. 247. Não sendo encontrada a pessoa ou coisa procurada, os motivos da diligência serão comunicados a quem tiver sofrido a busca, se o requerer."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:248","law":"cpp","ref":"248","label":"CPP — art. 248","paragraphs":["Art. 248. Em casa habitada, a busca será feita de modo que não moleste os moradores mais do que o indispensável para o êxito da diligência."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:249","law":"cpp","ref":"249","label":"CPP — art. 249","paragraphs":["Art. 249. A busca em mulher será feita por outra mulher, se não importar retardamento ou prejuízo da diligência."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:250","law":"cpp","ref":"250","label":"CPP — art. 250","paragraphs":["Art. 250. A autoridade ou seus agentes poderão penetrar no território de jurisdição alheia, ainda que de outro Estado, quando, para o fim de apreensão, forem no seguimento de pessoa ou coisa, devendo apresentar-se à competente autoridade local, antes da diligência ou após, conforme a urgência desta.","§ 1º Entender-se-á que a autoridade ou seus agentes vão em seguimento da pessoa ou coisa, quando:","a) tendo conhecimento direto de sua remoção ou transporte, a seguirem sem interrupção, embora depois a percam de vista;","b) ainda que não a tenham avistado, mas sabendo, por informações fidedignas ou circunstâncias indiciárias, que está sendo removida ou transportada em determinada direção, forem ao seu encalço.","§ 2º Se as autoridades locais tiverem fundadas razões para duvidar da legitimidade das pessoas que, nas referidas diligências, entrarem pelos seus distritos, ou da legalidade dos mandados que apresentarem, poderão exigir as provas dessa legitimidade, mas de modo que não se frustre a diligência."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"eca:239","law":"eca","ref":"239","label":"ECA — art. 239","paragraphs":["Art. 239. Promover ou auxiliar a efetivação de ato destinado ao envio de criança ou adolescente para o exterior com inobservância das formalidades legais ou com o fito de obter lucro:","Pena - reclusão de quatro a seis anos, e multa.","Parágrafo único. Se há emprego de violência, grave ameaça ou fraude:","Pena - reclusão, de 6 (seis) a 8 (oito) anos, além da pena correspondente à violência. (Parágrafo único acrescido pela Lei nº 10.764, de 12/11/2003)"],"url":"https://www2.camara.leg.br/legin/fed/lei/1990/lei-8069-13-julho-1990-372211-normaatualizada-pl.html"},{"key":"eca:240","law":"eca","ref":"240","label":"ECA — art. 240","paragraphs":["Art. 240. Produzir, reproduzir, dirigir, fotografar, filmar ou registrar, por qualquer meio, conteúdo de violência sexual contra criança ou adolescente: (“Caput” do artigo com redação dada pela Lei nº 15.487, de 6/8/2026)","Pena - reclusão, de 4 (quatro) a 10 (dez) anos, e multa. (Pena com redação dada pela Lei nº 15.487, de 6/8/2026)","§ 1º Incorre nas mesmas penas quem: (Parágrafo com redação dada pela Lei nº 14.811, de 12/1/2024)","I - financia, agencia, facilita, recruta, coage ou de qualquer modo intermedeia a participação de criança ou adolescente no conteúdo referido no caput deste artigo, ou ainda quem com eles contracena; (Inciso acrescido pela Lei nº 14.811, de 12/1/2024, e com redação dada pela Lei nº 15.487, de 6/8/2026)","II - exibe, transmite, auxilia ou facilita a exibição ou a transmissão, em tempo real, pela internet, por aplicativos, por meio de dispositivo informático ou qualquer meio ou ambiente digital, de conteúdo de violência sexual contra criança ou adolescente. (Inciso acrescido pela Lei nº 14.811, de 12/1/2024, e com redação dada pela Lei nº 15.487, de 6/8/2026)","§ 2º Aumenta-se a pena de 1/3 (um terço) a 2/3 (dois terços) se o agente comete o crime: (Parágrafo com redação dada pela Lei nº 15.487, de 6/8/2026)","I - no exercício de cargo ou função pública ou a pretexto de exercê-la; (Inciso com redação dada pela Lei nº 11.829, de 25/11/2008)","II - prevalecendo-se de relações domésticas, de coabitação ou de hospitalidade; ou (Inciso com redação dada pela Lei nº 11.829, de 25/11/2008)","III - prevalecendo-se de relações de parentesco consangüíneo ou afim até o terceiro grau, ou por adoção, de tutor, curador, preceptor, empregador da vítima ou de quem, a qualquer outro título, tenha autoridade sobre ela, ou com seu consentimento. (Inciso acrescido pela Lei nº 11.829, de 25/11/2008)"],"url":"https://www2.camara.leg.br/legin/fed/lei/1990/lei-8069-13-julho-1990-372211-normaatualizada-pl.html"},{"key":"eca:241","law":"eca","ref":"241","label":"ECA — art. 241","paragraphs":["Art. 241. Vender ou expor à venda fotografia, vídeo ou outro registro que contenha violência sexual contra criança ou adolescente: (“Caput” do artigo com redação dada pela Lei nº 15.487, de 6/8/2026)","Pena - reclusão, de 4 (quatro) a 10 (dez) anos, e multa, além da perda de bens e valores recebidos em virtude da prática criminosa em favor do Fundo dos Direitos da Criança e do Adolescente da unidade da Federação em que foi cometido o crime, ressalvado o direito de terceiro de boa-fé. (Pena com redação dada pela Lei nº 15.487, de 6/8/2026)","Parágrafo único. Aumenta-se a pena de 1/3 (um terço) caso a venda ou a exposição à venda prevista no caput deste artigo ocorra por meio de tecnologias da informação e comunicação, incluídas a internet e suas aplicações, bem como as redes sociais. (Parágrafo único acrescido pela Lei nº 15.487, de 6/8/2026)"],"url":"https://www2.camara.leg.br/legin/fed/lei/1990/lei-8069-13-julho-1990-372211-normaatualizada-pl.html"},{"key":"eca:241-A","law":"eca","ref":"241-A","label":"ECA — art. 241-A","paragraphs":["Art. 241-A. Oferecer, trocar, disponibilizar, transmitir, distribuir, publicar ou divulgar por qualquer meio, inclusive por meio de sistema de informática ou telemático, fotografia, vídeo ou outro registro que contenha violência sexual contra criança ou adolescente: (“Caput” do artigo acrescido pela Lei nº 11.829, de 25/11/2008, e com redação dada pela Lei nº 15.487, de 6/8/2026)","Pena - reclusão, de 4 (quatro) a 10 (dez) anos, e multa. (Pena acrescida pela Lei nº 11.829, de 25/11/2008, e com redação dada pela Lei nº 15.487, de 6/8/2026)","§ 1º Nas mesmas penas incorre quem: (Parágrafo acrescido pela Lei nº 11.829, de 25/11/2008)","I - assegura os meios ou serviços para o armazenamento das fotografias, cenas ou imagens de que trata o caput deste artigo; (Inciso acrescido pela Lei nº 11.829, de 25/11/2008)","II - assegura, por qualquer meio, o acesso por rede de computadores às fotografias, cenas ou imagens de que trata o caput deste artigo. (Inciso acrescido pela Lei nº 11.829, de 25/11/2008)","III - cria, administra, hospeda, modera ou é responsável por site, chat, fórum ou ambiente cibernético similar com o fim de armazenar, disponibilizar, compartilhar ou produzir material de violência sexual contra criança ou adolescente. (Inciso acrescido pela Lei nº 15.487, de 6/8/2026)","§ 2º As condutas tipificadas nos incisos I e II do § 1º deste artigo são puníveis quando o responsável legal pela prestação do serviço, oficialmente notificado, deixa de desabilitar o acesso ao conteúdo ilícito de que trata o caput deste artigo. (Parágrafo acrescido pela Lei nº 11.829, de 25/11/2008)","§ 3º A pena é aumentada de 1/3 (um terço) quando, em relação ao conteúdo previsto no caput deste artigo, houver publicação ou compartilhamento em mais de uma plataforma digital, rede social, serviço de vídeo sob demanda ou aplicativo acessível ao público em geral. (Parágrafo acrescido pela Lei nº 15.487, de 6/8/2026)"],"url":"https://www2.camara.leg.br/legin/fed/lei/1990/lei-8069-13-julho-1990-372211-normaatualizada-pl.html"},{"key":"eca:241-B","law":"eca","ref":"241-B","label":"ECA — art. 241-B","paragraphs":["Art. 241-B. Adquirir, possuir, armazenar ou solicitar, por qualquer meio, fotografia, vídeo ou outra forma de registro que contenha violência sexual contra criança ou adolescente: (“Caput” do artigo acrescido pela Lei nº 11.829, de 25/11/2008, e com redação dada pela Lei nº 15.487, de 6/8/2026)","Pena - reclusão, de 3 (três) a 6 (seis) anos, e multa. (Pena acrescida pela Lei nº 11.829, de 25/11/2008, e com redação dada pela Lei nº 15.487, de 6/8/2026)","§ 1º A pena é diminuída de 1/6 (um sexto) a 1/3 (um terço) se for pequena a quantidade de material a que se refere o caput deste artigo. (Parágrafo acrescido pela Lei nº 11.829, de 25/11/2008, e com redação dada pela Lei nº 15.487, de 6/8/2026)","§ 2º Não há crime se a posse ou o armazenamento tem a finalidade de comunicar às autoridades competentes a ocorrência das condutas descritas nos arts. 240, 241, 241-A e 241-C desta Lei, quando a comunicação for feita por:","I - agente público no exercício de suas funções;","II - membro de entidade, legalmente constituída, que inclua, entre suas finalidades institucionais, o recebimento, o processamento e o encaminhamento de notícia dos crimes referidos neste parágrafo;","III - representante legal e funcionários responsáveis de provedor de acesso ou serviço prestado por meio de rede de computadores, até o recebimento do material relativo à notícia feita à autoridade policial, ao Ministério Público ou ao Poder Judiciário. (Parágrafo acrescido pela Lei nº 11.829, de 25/11/2008)","§ 3º As pessoas referidas no § 2º deste artigo deverão manter sob sigilo o material ilícito referido. (Parágrafo acrescido pela Lei nº 11.829, de 25/11/2008)","§ 4º Incorre na mesma pena prevista no caput deste artigo quem acessar ou visualizar aplicações de internet, serviços de streaming ou outra forma de registro que disponibilize material de violência sexual contra criança ou adolescente, com a finalidade de satisfazer a própria lascívia ou de outrem. (Parágrafo acrescido pela Lei nº 15.487, de 6/8/2026)"],"url":"https://www2.camara.leg.br/legin/fed/lei/1990/lei-8069-13-julho-1990-372211-normaatualizada-pl.html"},{"key":"eca:241-C","law":"eca","ref":"241-C","label":"ECA — art. 241-C","paragraphs":["Art. 241-C. Simular a participação de criança ou adolescente em conteúdo de violência sexual por meio de adulteração, montagem ou modificação de fotografia, vídeo ou outra forma de representação visual, mediante qualquer recurso tecnológico que altere imagem ou voz da vítima, inclusive com uso de inteligência artificial: (“Caput” do artigo acrescido pela Lei nº 11.829, de 25/11/2008, e com redação dada pela Lei nº 15.487, de 6/8/2026)","Pena - reclusão, de 3 (três) a 5 (cinco) anos, e multa. (Pena acrescida pela Lei nº 11.829, de 25/11/2008, e com redação dada pela Lei nº 15.487, de 6/8/2026)","Parágrafo único. Incorre nas mesmas penas quem vende, expõe à venda, disponibiliza, distribui, publica ou divulga por qualquer meio, adquire, possui ou armazena o material produzido na forma do caput deste artigo. (Parágrafo único acrescido pela Lei nº 11.829, de 25/11/2008)"],"url":"https://www2.camara.leg.br/legin/fed/lei/1990/lei-8069-13-julho-1990-372211-normaatualizada-pl.html"},{"key":"eca:241-D","law":"eca","ref":"241-D","label":"ECA — art. 241-D","paragraphs":["Art. 241-D. Aliciar, assediar, convidar, instigar ou constranger, por qualquer meio, menor de 14 (quatorze) anos, com o fim de praticar ato libidinoso: (“Caput” do artigo acrescido pela Lei nº 11.829, de 25/11/2008, e com redação dada pela Lei nº 15.487, de 6/8/2026)","Pena - reclusão, de 3 (três) a 5 (cinco) anos, e multa, se o fato não constituir crime mais grave. (Pena acrescida pela Lei nº 11.829, de 25/11/2008, e com redação dada pela Lei nº 15.487, de 6/8/2026)","§ 1º Nas mesmas penas incorre quem: (Parágrafo único acrescido pela Lei nº 11.829, de 25/11/2008, e transformado em §1º pela Lei nº 15.487, de 6/8/2026)","I - permite, facilita ou induz o acesso de menor de 14 (quatorze) anos a material que contenha cena de sexo explícito ou nudez com o fim de com ele praticar ato libidinoso; (Inciso acrescido pela Lei nº 11.829, de 25/11/2008, e com redação dada pela Lei nº 15.487, de 6/8/2026)","II - pratica as condutas descritas no caput deste artigo com o fim de induzir menor de 14 (quatorze) anos a se exibir de forma lasciva ou sexualmente explícita. (Inciso acrescido pela Lei nº 11.829, de 25/11/2008, e com redação dada pela Lei nº 15.487, de 6/8/2026)","§ 2º A pena é aumentada de 1/3 (um terço) a 2/3 (dois terços) se o agente pratica as condutas previstas no caput e no § 1º deste artigo:","I - utilizando recursos de inteligência artificial, deepfake, filtros ou qualquer outro recurso tecnológico que permita ao autor alterar sua imagem e voz, fazendo-se passar por criança ou adolescente, com o fim de induzir a vítima a se exibir de forma lasciva ou sexualmente explícita ou a fornecer fotografias ou vídeos sexuais ou sensuais;","II - utilizando recursos de anonimização ou identidade ou perfil falsos, ocultando sua verdadeira idade ou empregando qualquer outra forma de ocultação digital;","III - utilizando aplicativos de mensagens instantâneas, salas de bate-papo, redes sociais, jogos online ou qualquer outro meio digital;","IV - prometendo à vítima qualquer tipo de vantagem;","V - valendo-se de relação de confiança, autoridade, cuidado, proteção, vigilância, educação ou convivência familiar ou profissional. (Parágrafo acrescido pela Lei nº 15.487, de 6/8/2026)"],"url":"https://www2.camara.leg.br/legin/fed/lei/1990/lei-8069-13-julho-1990-372211-normaatualizada-pl.html"},{"key":"eca:244-A","law":"eca","ref":"244-A","label":"ECA — art. 244-A","paragraphs":["Art. 244-A. Submeter criança ou adolescente, como tais definidos no caput do art. 2º desta Lei, à exploração sexual, se o fato não constituir crime mais grave: (“Caput” do artigo acrescido pela Lei nº 9.975, de 23/6/2000, e com redação dada pela Lei nº 15.487, de 6/8/2026)","Pena - reclusão de quatro a dez anos e multa, além da perda de bens e valores utilizados na prática criminosa em favor do Fundo dos Direitos da Criança e do Adolescente da unidade da Federação (Estado ou Distrito Federal) em que foi cometido o crime, ressalvado o direito de terceiro de boa-fé. (Pena acrescida pela Lei nº 9.975, de 23/6/2000, com redação dada pela Lei nº 13.440, de 8/5/2017)","§ 1º Incorrem nas mesmas penas o proprietário, o gerente ou o responsável pelo local em que se verifique a submissão de criança ou adolescente às práticas referidas no caput deste artigo. (Parágrafo acrescido pela Lei nº 9.975, de 23/6/2000)","§ 2º Constitui efeito obrigatório da condenação a cassação da licença de localização e de funcionamento do estabelecimento. (Parágrafo acrescido pela Lei nº 9.975, de 23/6/2000)"],"url":"https://www2.camara.leg.br/legin/fed/lei/1990/lei-8069-13-julho-1990-372211-normaatualizada-pl.html"},{"key":"cpp:161","law":"cpp","ref":"161","label":"CPP — art. 161","paragraphs":["Art. 161. O exame de corpo de delito poderá ser feito em qualquer dia e a qualquer hora."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:163","law":"cpp","ref":"163","label":"CPP — art. 163","paragraphs":["Art. 163. Em caso de exumação para exame cadavérico, a autoridade providenciará para que, em dia e hora previamente marcados, se realize a diligência, da qual se lavrará auto circunstanciado.","Parágrafo único. O administrador de cemitério público ou particular indicará o lugar da sepultura, sob pena de desobediência. No caso de recusa ou de falta de quem indique a sepultura, ou de encontrar-se o cadáver em lugar não destinado a inumações, a autoridade procederá às pesquisas necessárias, o que tudo constará do auto."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:164","law":"cpp","ref":"164","label":"CPP — art. 164","paragraphs":["Art. 164. Os cadáveres serão sempre fotografados na posição em que forem encontrados, bem como, na medida do possível, todas as lesões externas e vestígios deixados no local do crime. (Artigo com redação dada pela Lei nº 8.862, de 28/3/1994)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:165","law":"cpp","ref":"165","label":"CPP — art. 165","paragraphs":["Art. 165. Para representar as lesões encontradas no cadáver, os peritos, quando possível, juntarão ao laudo do exame provas fotográficas, esquemas ou desenhos, devidamente rubricados."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:166","law":"cpp","ref":"166","label":"CPP — art. 166","paragraphs":["Art. 166. Havendo dúvida sobre a identidade do cadáver exumado, proceder-se-á ao reconhecimento pelo Instituto de Identificação e Estatística ou repartição congênere ou pela inquirição de testemunhas, lavrando-se auto de reconhecimento e de identidade, no qual se descreverá o cadáver, com todos os sinais e indicações.","Parágrafo único. Em qualquer caso, serão arrecadados e autenticados todos os objetos encontrados, que possam ser úteis para a identificação do cadáver."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:169","law":"cpp","ref":"169","label":"CPP — art. 169","paragraphs":["Art. 169. Para o efeito de exame do local onde houver sido praticada a infração, a autoridade providenciará imediatamente para que não se altere o estado das coisas até a chegada dos peritos, que poderão instruir seus laudos com fotografias, desenhos ou esquemas elucidativos.","Parágrafo único. Os peritos registrarão, no laudo, as alterações do estado das coisas e discutirão, no relatório, as conseqüências dessas alterações na dinâmica dos fatos. (Parágrafo único acrescido pela Lei nº 8.862, de 28/3/1994)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:170","law":"cpp","ref":"170","label":"CPP — art. 170","paragraphs":["Art. 170. Nas perícias de laboratório, os peritos guardarão material suficiente para a eventualidade de nova perícia. Sempre que conveniente, os laudos serão ilustrados com provas fotográficas, ou microfotográficas, desenhos ou esquemas."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:171","law":"cpp","ref":"171","label":"CPP — art. 171","paragraphs":["Art. 171. Nos crimes cometidos com destruição ou rompimento de obstáculo à subtração da coisa, ou por meio de escalada, os peritos, além de descrever os vestígios, indicarão com que instrumentos, por que meios e em que época presumem ter sido o fato praticado."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:172","law":"cpp","ref":"172","label":"CPP — art. 172","paragraphs":["Art. 172. Proceder-se-á, quando necessário, à avaliação de coisas destruídas, deterioradas ou que constituam produto do crime.","Parágrafo único. Se impossível a avaliação direta, os peritos procederão à avaliação por meio dos elementos existentes nos autos e dos que resultarem de diligências."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:173","law":"cpp","ref":"173","label":"CPP — art. 173","paragraphs":["Art. 173. No caso de incêndio, os peritos verificarão a causa e o lugar em que houver começado, o perigo que dele tiver resultado para a vida ou para o patrimônio alheio, a extensão do dano e o seu valor e as demais circunstâncias que interessarem à elucidação do fato."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:174","law":"cpp","ref":"174","label":"CPP — art. 174","paragraphs":["Art. 174. No exame para o reconhecimento de escritos, por comparação de letra, observar-se-á o seguinte:","I - a pessoa a quem se atribua ou se possa atribuir o escrito será intimada para o ato, se for encontrada;","II - para a comparação, poderão servir quaisquer documentos que a dita pessoa reconhecer ou já tiverem sido judicialmente reconhecidos como de seu punho, ou sobre cuja autenticidade não houver dúvida;","III - a autoridade, quando necessário, requisitará, para o exame, os documentos que existirem em arquivos ou estabelecimentos públicos, ou nestes realizará a diligência, se daí não puderem ser retirados;","IV - quando não houver escritos para a comparação ou forem insuficientes os exibidos, a autoridade mandará que a pessoa escreva o que lhe for ditado. Se estiver ausente a pessoa, mas em lugar certo, esta última diligência poderá ser feita por precatória, em que se consignarão as palavras que a pessoa será intimada a escrever."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:175","law":"cpp","ref":"175","label":"CPP — art. 175","paragraphs":["Art. 175. Serão sujeitos a exame os instrumentos empregados para a prática da infração, a fim de se lhes verificar a natureza e a eficiência."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:176","law":"cpp","ref":"176","label":"CPP — art. 176","paragraphs":["Art. 176. A autoridade e as partes poderão formular quesitos até o ato da diligência."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:177","law":"cpp","ref":"177","label":"CPP — art. 177","paragraphs":["Art. 177. No exame por precatória, a nomeação dos peritos far-se-á no juízo deprecado. Havendo, porém, no caso de ação privada, acordo das partes, essa nomeação poderá ser feita pelo juiz deprecante.","Parágrafo único. Os quesitos do juiz e das partes serão transcritos na precatória."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:178","law":"cpp","ref":"178","label":"CPP — art. 178","paragraphs":["Art. 178. No caso do art. 159, o exame será requisitado pela autoridade ao diretor da repartição, juntando-se ao processo o laudo assinado pelos peritos."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:179","law":"cpp","ref":"179","label":"CPP — art. 179","paragraphs":["Art. 179. No caso do § 1º do art. 159, o escrivão lavrará o auto respectivo, que será assinado pelos peritos e, se presente ao exame, também pela autoridade.","Parágrafo único. No caso do art. 160, parágrafo único, o laudo, que poderá ser datilografado, será subscrito e rubricado em suas folhas por todos os peritos."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:180","law":"cpp","ref":"180","label":"CPP — art. 180","paragraphs":["Art. 180. Se houver divergência entre os peritos, serão consignadas no auto do exame as declarações e respostas de um e de outro, ou cada um redigirá separadamente o seu laudo, e a autoridade nomeará um terceiro; se este divergir de ambos, a autoridade poderá mandar proceder a novo exame por outros peritos."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:181","law":"cpp","ref":"181","label":"CPP — art. 181","paragraphs":["Art. 181. No caso de inobservância de formalidades, ou no caso de omissões, obscuridades ou contradições, a autoridade judiciária mandará suprir a formalidade, complementar ou esclarecer o laudo. (“Caput” do artigo com redação dada pela Lei nº 8.862, de 28/3/1994)","Parágrafo único. A autoridade poderá também ordenar que se proceda a novo exame, por outros peritos, se julgar conveniente."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:183","law":"cpp","ref":"183","label":"CPP — art. 183","paragraphs":["Art. 183. Nos crimes em que não couber ação pública, observar-se-á o disposto no art. 19."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:184","law":"cpp","ref":"184","label":"CPP — art. 184","paragraphs":["Art. 184. Salvo o caso de exame de corpo de delito, o juiz ou a autoridade policial negará a perícia requerida pelas partes, quando não for necessária ao esclarecimento da verdade."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:222-A","law":"cpp","ref":"222-A","label":"CPP — art. 222-A","paragraphs":["Art. 222-A. As cartas rogatórias só serão expedidas se demonstrada previamente a sua imprescindibilidade, arcando a parte requerente com os custos de envio.","Parágrafo único. Aplica-se às cartas rogatórias o disposto nos §§ 1º e 2º do art. 222 deste Código. (Artigo acrescido pela Lei nº 11.900, de 8/1/2009)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"}];})(window);
